package com.veyra.address;import com.veyra.provider.RoutingProvider;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/routes") public class RoutingController{private final RoutingProvider r;public RoutingController(RoutingProvider r){this.r=r;}@GetMapping("/estimate")public Map<String,Object> estimate(@RequestParam double fromLat,@RequestParam double fromLng,@RequestParam double toLat,@RequestParam double toLng){var x=r.route(fromLat,fromLng,toLat,toLng);Map<String,Object>m=new LinkedHashMap<>();m.put("distanceMeters",x.distanceMeters());m.put("durationSeconds",x.durationSeconds());m.put("points",x.points()==null?List.of():x.points());return m;}}